-- No new business records may cross a captured annual boundary before its rollover commits.
CREATE TRIGGER annual_quiz_insert BEFORE INSERT ON Quiz WHEN EXISTS(SELECT 1 FROM ArchiveSnapshot s JOIN AcademicYear y ON y.id=s.academicYearId WHERE s.mode='annual' AND s.capturedAt IS NOT NULL AND s.status<>'completed' AND y.status='active') BEGIN SELECT RAISE(ABORT,'ANNUAL_CAPTURE_FROZEN'); END;
